package whirlpool

// compressAsm is the arm64 kernel in compress_arm64.s, generated by
// internal/genasm. t holds the eight tables, then the round constants.
//
//go:noescape
func compressAsm(h *[8]uint64, p *byte, t *tables)

// compress is the Miyaguchi-Preneel step h = W_h(m) ^ h ^ m for one 64-byte
// block.
func compress(h *[8]uint64, block []byte) {
	_ = block[BlockSize-1]
	compressAsm(h, &block[0], &tab)
}
